command:
$ErrorActionPreference = 'Stop'
$targets = [ordered]@{
  'test/dcoir-review-canary-20260911b' = 'cf36940ac46c313c054e01a40d7ecb8536f94efa'
  'test/dcoir-review-canary-20260911c' = '7c24ead9340f2dd4abb9030f3e92dcb34ed6ae49'
  'test/dcoir-review-canary-20260911d' = 'f128222ab4fbf885687b7c2e288500e8d5b240c1'
  'test/dcoir-review-canary-final' = '9b76c909ec18d5359777584e05aea923f2673132'
  'agent-ops-temp-guard-probe' = '9edc68f68e596bfe320b38296626487924a8055a'
  'agent-ops-temp-guard-probe-2' = '9edc68f68e596bfe320b38296626487924a8055a'
  'agent-ops-temp-guard-probe-3' = '9edc68f68e596bfe320b38296626487924a8055a'
  'agent-ops-temp-guard-probe-4' = '9edc68f68e596bfe320b38296626487924a8055a'
  'agent-ops-temp-guard-probe-5' = '9edc68f68e596bfe320b38296626487924a8055a'
  'agent-ops-temp-guard-probe-6' = '9edc68f68e596bfe320b38296626487924a8055a'
}
$protected = @('main','agent-ops','test/dcoir-review-canary-20260911a')
foreach ($branch in $targets.Keys) {
  if ($protected -contains $branch) { throw "Protected branch appeared in deletion targets: $branch" }
  $ref = "refs/heads/$branch"
  $before = @(git ls-remote --heads origin $ref)
  if ($LASTEXITCODE -ne 0) { throw "Failed to read remote branch head for $branch." }
  if ($before.Count -eq 0) { Write-Output "Already absent: $branch"; continue }
  $actualHead = (($before[0] -split '\s+')[0]).Trim()
  $expectedHead = $targets[$branch]
  if ($actualHead -ne $expectedHead) { throw "Refusing deletion: $branch moved from expected $expectedHead to $actualHead." }
  git push origin --delete $branch
  if ($LASTEXITCODE -ne 0) { throw "git push --delete failed for $branch." }
  $after = @(git ls-remote --heads origin $ref)
  if ($LASTEXITCODE -ne 0) { throw "Failed to verify remote branch deletion for $branch." }
  if ($after.Count -ne 0) { throw "Branch $branch still exists after deletion attempt." }
  Write-Output "Deleted and verified absent: $branch@$expectedHead"
}
foreach ($branch in $protected) {
  $ref = "refs/heads/$branch"
  $present = @(git ls-remote --heads origin $ref)
  if ($LASTEXITCODE -ne 0 -or $present.Count -eq 0) { throw "Protected branch missing after cleanup: $branch" }
}
Write-Output 'Unused canary branch cleanup complete; protected refs remain present.'
